// Triagem de cadastros de prestadores - SOS Driver
const COBERTURA = ['são paulo','guarulhos','osasco','santo andré','são bernardo do campo','são caetano do sul'];
const OBRIGATORIOS = ['id','nome','documento','telefone','email','tipo_servico','cidade','validade_habilitacao'];
const TIPOS = ['guincho','mecanico','socorrista','chaveiro'];
const agora = new Date().toISOString();
const itens = $input.all().map(i => i.json);

const soDigitos = v => String(v ?? '').replace(/\D/g, '');
const mascara = v => { const d = soDigitos(v); return d.length < 6 ? '***' : d.slice(0,3) + '.***.***-' + d.slice(-2); };

function cpfOk(c) {
  if (c.length !== 11 || /^(\d)\1+$/.test(c)) return false;
  for (let t = 9; t < 11; t++) {
    let s = 0;
    for (let i = 0; i < t; i++) s += Number(c[i]) * (t + 1 - i);
    if (((s * 10) % 11) % 10 !== Number(c[t])) return false;
  }
  return true;
}
function cnpjOk(c) {
  if (c.length !== 14 || /^(\d)\1+$/.test(c)) return false;
  const dv = n => { let p = n - 7, s = 0; for (let i = 0; i < n; i++) { s += Number(c[i]) * p--; if (p < 2) p = 9; } const r = s % 11; return r < 2 ? 0 : 11 - r; };
  return dv(12) === Number(c[12]) && dv(13) === Number(c[13]);
}

// Estrutura do arquivo: sem linhas ou sem colunas obrigatórias = lote inválido (nunca falha em silêncio)
if (itens.length === 0 || OBRIGATORIOS.some(col => !(col in itens[0]))) {
  return [{ json: { id_externo: 'LOTE', documento_mascarado: '-', status: 'lote_invalido',
    motivos: ['Arquivo vazio ou sem as colunas obrigatórias: ' + OBRIGATORIOS.join(', ')], processado_em: agora } }];
}

const vistos = new Set();
const saida = [];
for (const r of itens) {                       // estrutura de repetição sobre o lote
  const motivosReprova = [];
  const motivosRevisao = [];
  const doc = soDigitos(r.documento);
  const id = String(r.id || '').trim() || 'SEM-ID';

  if (!(cpfOk(doc) || cnpjOk(doc))) motivosReprova.push('Documento inválido');
  if (doc && vistos.has(doc)) motivosReprova.push('Cadastro duplicado no lote');
  if (doc) vistos.add(doc);

  const validade = new Date(String(r.validade_habilitacao || '').trim());
  if (isNaN(validade.getTime())) motivosRevisao.push('Data de validade ausente ou ilegível');
  else if (validade < new Date()) motivosReprova.push('Habilitação/licença vencida');

  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(r.email || ''))) motivosRevisao.push('E-mail inválido');
  const tel = soDigitos(r.telefone);
  if (tel.length < 10 || tel.length > 11) motivosRevisao.push('Telefone inválido');
  if (!TIPOS.includes(String(r.tipo_servico || '').toLowerCase().trim())) motivosRevisao.push('Tipo de serviço desconhecido');
  if (!COBERTURA.includes(String(r.cidade || '').toLowerCase().trim())) motivosRevisao.push('Cidade fora da área de cobertura');

  let status = 'aprovado';                      // estrutura de decisão
  if (motivosReprova.length) status = 'reprovado';
  else if (motivosRevisao.length) status = 'revisao_manual';

  saida.push({ json: {
    id_externo: id,
    documento_mascarado: mascara(doc),
    status,
    motivos: [...motivosReprova, ...motivosRevisao],
    processado_em: agora,
    versao_codigo: 'v2',
    payload: { id_externo: id, nome: String(r.nome).trim(), tipo_servico: String(r.tipo_servico).toLowerCase().trim(),
               cidade: String(r.cidade).trim(), telefone: tel, validade_habilitacao: String(r.validade_habilitacao).trim() }
  } });
}
return saida;

// Consolida o lote, confere a entrega ao MVP e monta o log de auditoria (sem dados sensíveis)
const agora = new Date().toISOString();
const base = $('Validar cadastros').all().map(i => i.json);
let respostas = [];
try { respostas = $('Enviar ao MVP').all().map(i => i.json); } catch (e) { respostas = []; }
const entregues = new Set(respostas.filter(r => r && r.id_externo).map(r => r.id_externo));

const c = { aprovado_entregue: 0, revisao_manual: 0, reprovado: 0, falha_integracao: 0, lote_invalido: 0 };
const linhas = [];
for (const r of base) {
  let status = r.status;
  const motivos = (r.motivos || []).slice();
  if (status === 'aprovado') {
    if (entregues.has(r.id_externo)) status = 'aprovado_entregue';
    else { status = 'falha_integracao'; motivos.push('API do MVP indisponível ou rejeitou o registro'); }
  }
  c[status] = (c[status] || 0) + 1;
  linhas.push(`${r.processado_em} | ${r.id_externo} | doc ${r.documento_mascarado} | ${status.toUpperCase()} | ${motivos.join('; ') || '-'}`);
}
const nivel = (c.falha_integracao || c.lote_invalido) ? 'ERRO' : 'INFO';
const cab = `${agora} | ${nivel} | LOTE FINALIZADO | total=${base.length} entregues_ao_mvp=${c.aprovado_entregue} revisao_manual=${c.revisao_manual} reprovados=${c.reprovado} falhas_integracao=${c.falha_integracao} lote_invalido=${c.lote_invalido}`;
const texto = [cab, ...linhas].join('\n') + '\n';
const nome = 'log_triagem_' + agora.replace(/[-:T]/g, '').slice(0, 14) + '.txt';
const bin = await this.helpers.prepareBinaryData(Buffer.from(texto, 'utf8'), nome, 'text/plain');
return [{ json: { nivel, resumo: cab, arquivo_log: nome }, binary: { data: bin } }];

// Arquivo do lote ausente ou ilegível: registra o erro em vez de falhar em silêncio
const agora = new Date().toISOString();
const entrada = ($input.all()[0] && $input.all()[0].json) || {};
const msg = (entrada.error && (entrada.error.message || entrada.error)) || 'arquivo ausente ou ilegível';
const texto = `${agora} | ERRO | LOTE NAO PROCESSADO | motivo=${String(msg).slice(0, 200)}\n`;
const nome = 'log_triagem_' + agora.replace(/[-:T]/g, '').slice(0, 14) + '.txt';
const bin = await this.helpers.prepareBinaryData(Buffer.from(texto, 'utf8'), nome, 'text/plain');
return [{ json: { nivel: 'ERRO', resumo: texto.trim(), arquivo_log: nome }, binary: { data: bin } }];
